-- Allpha Universe — Phase 11A Expanded Universal Agent Catalog
-- Allpha-specific universal roles inspired by the broad use-case taxonomy of
-- 500-AI-Agents-Projects; this migration does not copy upstream implementations.

on conflict(skill_key) do update set
 name=excluded.name,description=excluded.description,category=excluded.category,risk_level=excluded.risk_level,
 capability_keys=excluded.capability_keys,tool_domains=excluded.tool_domains,source_reference=excluded.source_reference,
 sort_order=excluded.sort_order,updated_at=timezone('utc',now());

on conflict(type_key) do update set
 name=excluded.name,description=excluded.description,category=excluded.category,default_skill_keys=excluded.default_skill_keys,
 recommended_capability_keys=excluded.recommended_capability_keys,default_autonomy_level=excluded.default_autonomy_level,
 risk_profile=excluded.risk_profile,source_reference=excluded.source_reference,sort_order=excluded.sort_order,
 updated_at=timezone('utc',now());

on conflict(character_key) do update set
 name=excluded.name,archetype=excluded.archetype,description=excluded.description,interaction_style=excluded.interaction_style,
 persona_defaults=excluded.persona_defaults,tone_defaults=excluded.tone_defaults,visual_profile=excluded.visual_profile,
 source_reference=excluded.source_reference,sort_order=excluded.sort_order,updated_at=timezone('utc',now());
